      const mockRecordBytes = new Uint8Array([1, 2, 3]);
      mockDelegatedRoutingClient.resolve.mockResolvedValue(mockRecordBytes);
      mockParseIpnsRecord.mockReturnValue({
        value: 'invalid-record-without-cid',
