+
+/**
+ * Returns the Faro instance, or undefined if not initialized.
+ */
+export function getFaroInstance(): Faro | undefined {
+  return faroInstance;
+}
+
+/**
+ * Initialize Grafana Faro observability SDK.
+ * No-op when VITE_FARO_URL is absent (local dev).
+ */
