1	import {
2	  initializeFaro,
3	  getWebInstrumentations,
4	  type Faro,
5	  type TransportItem,
6	  LogLevel,
7	} from '@grafana/faro-web-sdk';
8	import { ReactIntegration } from '@grafana/faro-react';
9	
10	/**
11	 * Sensitive field names that must be scrubbed from all Faro payloads.
12	 * Matches the CipherBox terminology standards from CLAUDE.md.
13	 */
14	const SENSITIVE_KEYS = new Set([
15	  'privateKey',
16	  'rootFolderKey',
17	  'folderKey',
18	  'fileKey',
19	  'accessToken',
20	  'ipnsPrivateKey',
21	  'teePublicKey',
22	  'userEmail',
23	]);
24	
25	/**
26	 * Detects hex-encoded cryptographic keys (64+ hex chars = 32+ bytes).
27	 */
28	const HEX_KEY_PATTERN = /^[0-9a-fA-F]{64,}$/;
29	
30	/**
31	 * Scrub a single value: redact hex keys and binary data.
32	 */
33	function scrubValue(value: unknown): unknown {
34	  if (typeof value === 'string' && HEX_KEY_PATTERN.test(value)) {
35	    return '[REDACTED_KEY]';
36	  }
37	  if (value instanceof ArrayBuffer || ArrayBuffer.isView(value)) {
38	    return '[REDACTED_BINARY]';
39	  }
40	  if (typeof value === 'object' && value !== null && 'buffer' in value && 'byteLength' in value) {
41	    return '[REDACTED_BINARY]';
42	  }
43	  return value;
44	}
45	
46	/**
47	 * Recursively scrub an object: redact sensitive keys and values.
48	 * Limited to 3 levels of depth to prevent infinite recursion.
49	 */
50	function scrubObject(obj: Record<string, unknown>, depth = 0): Record<string, unknown> {
51	  if (depth > 3) return obj;
52	
53	  const result: Record<string, unknown> = {};
54	  for (const key of Object.keys(obj)) {
55	    const value = obj[key];
56	
57	    if (SENSITIVE_KEYS.has(key)) {
58	      result[key] = '[REDACTED]';
59	      continue;
60	    }
61	
62	    const scrubbed = scrubValue(value);
63	    if (scrubbed !== value) {
64	      result[key] = scrubbed;
65	      continue;
66	    }
67	
68	    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
69	      result[key] = scrubObject(value as Record<string, unknown>, depth + 1);
70	    } else {
71	      result[key] = value;
72	    }
73	  }
74	  return result;
75	}
76	
77	/**
78	 * Privacy gate: scrubs all sensitive data from Faro transport items
79	 * before they leave the browser.
80	 */
81	function beforeSend(item: TransportItem): TransportItem | null {
82	  // Deep-scrub payload
83	  if (item.payload && typeof item.payload === 'object') {
84	    item = {
85	      ...item,
86	      payload: scrubObject(
87	        item.payload as unknown as Record<string, unknown>
88	      ) as TransportItem['payload'],
89	    };
90	  }
91	
92	  // Strip email from user meta — only publicKey (as id) is allowed
93	  if (item.meta?.user?.email) {
94	    item = {
95	      ...item,
96	      meta: {
97	        ...item.meta,
98	        user: {
99	          ...item.meta.user,
100	          email: undefined,
101	        },
102	      },
103	    };
104	  }
105	
106	  return item;
107	}
108	
109	let faroInstance: Faro | undefined;
110	
111	/**
112	 * Returns the Faro instance, or undefined if not initialized.
113	 */
114	export function getFaroInstance(): Faro | undefined {
115	  return faroInstance;
116	}
117	
118	/**
119	 * Initialize Grafana Faro observability SDK.
120	 * No-op when VITE_FARO_URL is absent (local dev).
121	 */
122	export function initFaro(): Faro | undefined {
123	  const faroUrl = import.meta.env.VITE_FARO_URL;
124	  if (!faroUrl) return undefined;
125	
126	  faroInstance = initializeFaro({
127	    url: faroUrl,
128	    app: {
129	      name: 'cipherbox-web',
130	      version: import.meta.env.VITE_APP_VERSION ?? 'dev',
131	      environment: import.meta.env.VITE_ENVIRONMENT ?? 'development',
132	    },
133	    instrumentations: [
134	      ...getWebInstrumentations({
135	        captureConsole: false, // Phase 28 logger handles console capture
136	      }),
137	      new ReactIntegration(),
138	    ],
139	    beforeSend,
140	    sessionTracking: {
141	      enabled: true,
142	      persistent: false, // Don't persist session across tabs
143	    },
144	  });
145	
146	  return faroInstance;
147	}
148	
149	/**
150	 * Set the current user identity on Faro (publicKey only, never email).
151	 */
152	export function setFaroUser(publicKey: string): void {
153	  const faro = getFaroInstance();
154	  if (!faro) return;
155	  faro.api.setUser({ id: publicKey });
156	}
157	
158	/**
159	 * Clear the current user identity from Faro (call on logout).
160	 */
161	export function clearFaroUser(): void {
162	  const faro = getFaroInstance();
163	  if (!faro) return;
164	  faro.api.setUser(null as unknown as Parameters<typeof faro.api.setUser>[0]);
165	}
166	
167	/**
168	 * Register a Faro transport that forwards warn/error log calls to Grafana.
169	 * Designed to integrate with Phase 28's logger transports array.
170	 * No-op if Faro is not initialized.
171	 *
172	 * @param loggerTransports - The transports array from the logger module.
173	 *   Each transport is called as (level, message, context?) for every log call.
174	 */
175	export function registerFaroTransport(
176	  loggerTransports: Array<
177	    (level: string, message: string, context?: Record<string, unknown>) => void
178	  >
179	): void {
180	  const faro = getFaroInstance();
181	  if (!faro) return;
182	
183	  const faroTransport = (
184	    level: string,
185	    message: string,
186	    context?: Record<string, unknown>
187	  ): void => {
188	    if (level === 'error') {
189	      const error = context?.error instanceof Error ? context.error : new Error(message);
190	      faro.api.pushError(error, {
191	        context: context
192	          ? Object.fromEntries(
193	              Object.entries(context)
194	                .filter(([k]) => k !== 'error')
195	                .map(([k, v]) => [k, String(v)])
196	            )
197	          : undefined,
198	      });
199	    } else if (level === 'warn') {
200	      faro.api.pushLog([message], {
201	        level: LogLevel.WARN,
202	        context: context
203	          ? Object.fromEntries(Object.entries(context).map(([k, v]) => [k, String(v)]))
204	          : undefined,
205	      });
206	    }
207	    // debug and info are not forwarded — noise reduction
208	  };
209	
210	  loggerTransports.push(faroTransport);
211	}
