27	  if (typeof value === 'string' && value.length >= 64 && HEX_KEY_PATTERN.test(value)) {
28	    return '[REDACTED_KEY]';
29	  }
30	  if (value instanceof ArrayBuffer || ArrayBuffer.isView(value)) {
31	    return '[REDACTED_BINARY]';
32	  }
33	  if (typeof value === 'object' && value !== null && 'buffer' in value && 'byteLength' in value) {
34	    return '[REDACTED_BINARY]';
35	  }
