39	/** Recursively scrub sensitive keys/values (max 3 levels deep). */
40	function scrubObject(obj: Record<string, unknown>, depth = 0): Record<string, unknown> {
41	  if (depth > 3) return obj;
42	
43	  const result: Record<string, unknown> = {};
44	  for (const key of Object.keys(obj)) {
45	    const value = obj[key];
46	
47	    if (SENSITIVE_KEYS.has(key)) {
48	      result[key] = '[REDACTED]';
49	      continue;
50	    }
51	
52	    const scrubbed = scrubValue(value);
53	    if (scrubbed !== value) {
54	      result[key] = scrubbed;
55	      continue;
56	    }
57	
58	    if (typeof value === 'object' && value !== null && !Array.isArray(value)) {
59	      result[key] = scrubObject(value as Record<string, unknown>, depth + 1);
60	    } else {
61	      result[key] = value;
62	    }
63	  }
64	  return result;
