67	/** Privacy gate: scrubs sensitive data before telemetry leaves the browser. */
68	function beforeSend(item: TransportItem): TransportItem | null {
69	  let modified = false;
70	  let payload = item.payload;
71	  let meta = item.meta;
72	
73	  // Deep-scrub payload
74	  if (payload && typeof payload === 'object') {
75	    payload = scrubObject(payload as unknown as Record<string, unknown>) as TransportItem['payload'];
76	    modified = true;
77	  }
78	
79	  // Strip email from user meta — only publicKey (as id) is allowed
80	  if (meta?.user?.email) {
81	    meta = { ...meta, user: { ...meta.user, email: undefined } };
82	    modified = true;
83	  }
