140	 * Integrates with Phase 28's logger transports array. No-op if Faro is not initialized.
141	 */
142	export function registerFaroTransport(
143	  loggerTransports: Array<
144	    (level: string, message: string, context?: Record<string, unknown>) => void
145	  >
146	): void {
147	  const faro = getFaroInstance();
148	  if (!faro) return;
149	
150	  const faroTransport = (
151	    level: string,
152	    message: string,
153	    context?: Record<string, unknown>
154	  ): void => {
155	    if (level === 'error') {
156	      const error = context?.error instanceof Error ? context.error : new Error(message);
157	      faro.api.pushError(error, {
158	        context: context
159	          ? Object.fromEntries(
160	              Object.entries(context)
161	                .filter(([k]) => k !== 'error')
162	                .map(([k, v]) => [k, typeof v === 'string' ? v : String(v)])
163	            )
164	          : undefined,
165	      });
166	    } else if (level === 'warn') {
167	      faro.api.pushLog([message], {
168	        level: LogLevel.WARN,
169	        context: context
170	          ? Object.fromEntries(
171	              Object.entries(context).map(([k, v]) => [k, typeof v === 'string' ? v : String(v)])
172	            )
173	          : undefined,
174	      });
175	    }
176	    // debug and info are not forwarded — noise reduction
177	  };
178	
