/**
 * @cipherbox/sdk-core - Tree traversal utilities
 *
 * Pure tree algorithms extracted from apps/web/src/services/folder.service.ts.
 * Framework-agnostic -- no React/Zustand dependencies.
 */

/**
 * Minimal folder node interface for tree operations.
 * Matches the shape used by both web FolderNode and SDK FolderState.
 */
export type TreeNode = {
  id: string;
  parentId: string | null;
};

/**
 * Calculate the depth of a folder in the tree.
 *
 * @param folderId - The folder ID to calculate depth for (null = root = depth 0)
 * @param folders - Map of folder ID to TreeNode
 * @returns Depth from root (root = 0, immediate child = 1, etc.)
 */
export function getDepth(folderId: string | null, folders: Record<string, TreeNode>): number {
  if (!folderId) return 0;
  let depth = 0;
  let current: string | null = folderId;
  while (current) {
    const node: TreeNode | undefined = folders[current];
    if (!node || !node.parentId) break;
    depth++;
    current = node.parentId;
  }
  return depth;
}

/**
 * Calculate the maximum depth of a folder's subtree.
 *
 * @param folderId - Root folder of the subtree
 * @param folders - Map of folder ID to TreeNode
 * @returns Maximum depth relative to folderId (0 if no children)
 */
export function calculateSubtreeDepth(
  folderId: string,
  folders: Record<string, TreeNode>,
): number {
  let maxDepth = 0;
  for (const [id, node] of Object.entries(folders)) {
    if (id === folderId) continue;
    // Check if this node is a descendant of folderId
    let current: string | null = node.parentId;
    let depth = 0;
    while (current) {
      depth++;
      if (current === folderId) {
        maxDepth = Math.max(maxDepth, depth);
        break;
      }
      const parent = folders[current];
      current = parent?.parentId ?? null;
    }
  }
  return maxDepth;
}

/**
 * Check if a folder is a descendant of another folder.
 *
 * @param childId - Potential descendant folder ID
 * @param ancestorId - Potential ancestor folder ID
 * @param folders - Map of folder ID to TreeNode
 * @returns true if childId is inside ancestorId's subtree
 */
export function isDescendantOf(
  childId: string,
  ancestorId: string,
  folders: Record<string, TreeNode>,
): boolean {
  let current: string | null = childId;
  while (current) {
    const node: TreeNode | undefined = folders[current];
    if (!node) return false;
    if (node.parentId === ancestorId) return true;
    current = node.parentId;
  }
  return false;
}

/**
 * @cipherbox/sdk - Error handling and retry utilities
 *
 * Framework-agnostic error detection and retry logic extracted from
 * apps/web/src/hooks/useSharedNavigation.ts and folder-helpers.ts.
 */

/**
 * Check if an error is a 403 Forbidden response (write access revoked).
 *
 * @param error - The caught error object
 * @returns true if the error represents a 403 status
 */
export function isForbiddenError(error: unknown): boolean {
  if (!error || typeof error !== 'object') return false;
  const e = error as Record<string, unknown>;
  return e.status === 403;
}

/**
 * Check if an error is a 409 Conflict response (concurrent modification).
 *
 * @param error - The caught error object
 * @returns true if the error represents a 409 status
 */
export function isConflictError(error: unknown): boolean {
  if (!error || typeof error !== 'object') return false;
  const e = error as Record<string, unknown>;
  if (e.status === 409) return true;
  if (typeof e.response === 'object' && e.response !== null) {
    return (e.response as Record<string, unknown>).status === 409;
  }
  return false;
}

/**
 * Wrap an operation with 403 revocation detection.
 * If the operation throws a 403, calls onRevoked() and re-throws a descriptive error.
 *
 * @param operation - The async operation to execute
 * @param onRevoked - Callback invoked when write access is revoked
 * @returns The operation's result
 * @throws Error with message containing 'write access revoked' on 403
 */
export async function withRevocationGuard<T>(
  operation: () => Promise<T>,
  onRevoked: () => void,
): Promise<T> {
  try {
    return await operation();
  } catch (err) {
    if (isForbiddenError(err)) {
      onRevoked();
      throw new Error('> write access revoked -- folder is now read-only');
    }
    throw err;
  }
}

/**
 * Execute an operation with single-retry on 409 conflict.
 *
 * On conflict: calls resync callback, adds jitter delay, optionally runs
 * pre-retry validation, then retries once. If retry also conflicts, throws.
 *
 * @param perform - The operation to attempt
 * @param resync - Callback to re-fetch fresh state after conflict
 * @param preRetry - Optional validation before retry attempt
 * @returns The operation's result
 */
export async function withConflictRetry<T>(
  perform: () => Promise<T>,
  resync: () => Promise<void>,
  preRetry?: () => void,
): Promise<T> {
  try {
    return await perform();
  } catch (err) {
    if (!isConflictError(err)) throw err;
    await resync();
    // Add jitter to reduce collision probability on retry
    await new Promise((r) => setTimeout(r, 200 + Math.random() * 300));
    if (preRetry) preRetry();
    try {
      return await perform();
    } catch (retryErr) {
      if (isConflictError(retryErr)) {
        throw new Error(
          'Folder was modified by another device. Please refresh and try again.',
        );
      }
      throw retryErr;
    }
  }
}

/**
 * @cipherbox/sdk - Shared write context builder
 *
 * Extracted from apps/web/src/hooks/useSharedNavigation.ts buildSharedWriteCtx().
 * Takes explicit params instead of reading React state directly.
 */

import type { FolderChild } from '@cipherbox/core';
import type { SdkContext } from '@cipherbox/sdk-core';
import type { SharedWriteContext, ShareKeyType } from './shared-write';

/**
 * Parameters for building a SharedWriteContext.
 * All the state that was previously read from React hooks.
 */
export type SharedWriteContextParams = {
  ctx: SdkContext;
  folderKey: Uint8Array;
  ipnsPrivateKey: Uint8Array;
  ipnsName: string;
  sequenceNumber: bigint;
  children: FolderChild[];
  ownerPublicKey: Uint8Array;
  recipientPublicKey: Uint8Array;
  shareId: string;
  addShareKeysFn: (
    shareId: string,
    keys: Array<{ keyType: ShareKeyType; itemId: string; encryptedKey: string }>,
  ) => Promise<void>;
};

/**
 * Build a SharedWriteContext from explicit parameters.
 *
 * The web hook wrapper handles null-checking of each field before calling this.
 * This function assumes all required fields are present.
 *
 * @param params - All required state for shared write operations
 * @returns SharedWriteContext ready for SDK shared-write operations
 */
export function buildSharedWriteContext(params: SharedWriteContextParams): SharedWriteContext {
  return {
    ctx: params.ctx,
    folderKey: params.folderKey,
    ipnsPrivateKey: params.ipnsPrivateKey,
    ipnsName: params.ipnsName,
    sequenceNumber: params.sequenceNumber,
    children: params.children,
    ownerPublicKey: params.ownerPublicKey,
    recipientPublicKey: params.recipientPublicKey,
    shareId: params.shareId,
    addShareKeysFn: params.addShareKeysFn,
  };
}

/**
 * @cipherbox/sdk - Share key cache with TTL
 *
 * Extracted from apps/web/src/hooks/useSharedNavigation.ts shareKeysCache ref.
 * Caches fetched share keys per shareId with a configurable TTL.
 */

/**
 * A cached share key entry.
 */
export type CachedShareKey = {
  keyType: string;
  itemId: string;
  encryptedKey: string;
};

/**
 * TTL-based cache for share keys.
 * Avoids redundant API calls when navigating within a share.
 */
export class ShareKeyCache {
  private cache = new Map<string, { keys: CachedShareKey[]; fetchedAt: number }>();
  private ttlMs: number;

  /**
   * @param ttlMs - Cache entry lifetime in milliseconds (default: 30000 = 30s)
   */
  constructor(ttlMs = 30_000) {
    this.ttlMs = ttlMs;
  }

  /**
   * Get cached keys for a share, or null if expired/missing.
   *
   * @param shareId - The share ID to look up
   * @returns Cached keys array or null
   */
  get(shareId: string): CachedShareKey[] | null {
    const entry = this.cache.get(shareId);
    if (!entry) return null;
    if (Date.now() - entry.fetchedAt > this.ttlMs) {
      this.cache.delete(shareId);
      return null;
    }
    return entry.keys;
  }

  /**
   * Store keys in the cache for a share.
   *
   * @param shareId - The share ID
   * @param keys - The share keys to cache
   */
  set(shareId: string, keys: CachedShareKey[]): void {
    this.cache.set(shareId, { keys, fetchedAt: Date.now() });
  }

  /**
   * Invalidate a specific share's cache entry.
   *
   * @param shareId - The share ID to invalidate
   */
  invalidate(shareId: string): void {
    this.cache.delete(shareId);
  }

  /** Clear all cached entries. */
  clear(): void {
    this.cache.clear();
  }
}

/**
 * useSharedNavigationActions -- Navigation action handlers for shared content.
 *
 * Extracted from useSharedNavigation.ts. Contains all navigation callbacks
 * including key unwrapping during share/subfolder entry, download, and hide.
 */

import { useCallback, type MutableRefObject } from 'react';
import {
  decryptFolderMetadata,
  decryptFileMetadata,
  type FolderChild,
  type FolderEntry,
  type FilePointer,
  type EncryptedFolderMetadata,
  type EncryptedFileMetadata,
} from '@cipherbox/core';
import { unwrapKey, hexToBytes } from '@cipherbox/crypto';
import { ShareKeyCache } from '@cipherbox/sdk';
import { useAuthStore } from '../stores/auth.store';
import { useShareStore } from '../stores/share.store';
import { hideShare } from '../services/share.service';
import { resolveIpnsRecord } from '../services/ipns.service';
import { fetchFromIpfs } from '../lib/api/ipfs';
import { downloadFile, triggerBrowserDownload } from '../services/download.service';
import { useDownloadStore } from '../stores/download.store';
import { logger } from '../lib/logger';
import type { SharedListItem, SharedBreadcrumb } from './useSharedNavigation';

type NavStackEntry = {
  folderId: string;
  folderName: string;
  children: FolderChild[];
  folderKey: Uint8Array;
  ipnsName: string;
  sequenceNumber: bigint | null;
};

export type SharedNavigationActionsParams = {
  sharedItems: SharedListItem[];
  folderChildren: FolderChild[];
  folderKey: Uint8Array | null;
  breadcrumbs: SharedBreadcrumb[];
  currentShareId: string | null;
  permission: 'read' | 'write' | null;
  ipnsName: string | null;
  currentSequenceNumber: bigint | null;
  currentView: 'list' | 'folder' | 'file';
  // Refs
  folderChildrenRef: MutableRefObject<FolderChild[]>;
  sequenceNumberRef: MutableRefObject<bigint | null>;
  ipnsPrivateKeyRef: MutableRefObject<Uint8Array | null>;
  navStackRef: MutableRefObject<NavStackEntry[]>;
  shareKeysCacheRef: MutableRefObject<ShareKeyCache>;
  // State setters
  setCurrentView: (view: 'list' | 'folder' | 'file') => void;
  setCurrentShareId: (id: string | null) => void;
  setFolderChildren: (children: FolderChild[]) => void;
  setFolderKey: (key: Uint8Array | null) => void;
  setBreadcrumbs: (crumbs: SharedBreadcrumb[] | ((prev: SharedBreadcrumb[]) => SharedBreadcrumb[])) => void;
  setPermission: (perm: 'read' | 'write' | null) => void;
  setIpnsName: (name: string | null) => void;
  setCurrentSequenceNumber: (seq: bigint | null) => void;
  setIsLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  setSharedItems: (updater: (prev: SharedListItem[]) => SharedListItem[]) => void;
  // Helpers from orchestrator
  clearPolling: () => void;
  zeroIpnsKey: () => void;
  getShareKeys: (shareId: string) => Promise<Array<{ keyType: string; itemId: string; encryptedKey: string }>>;
};

export function useSharedNavigationActions(p: SharedNavigationActionsParams) {
  /**
   * Navigate into a shared folder/file from the top-level list.
   */
  const navigateToShare = useCallback(
    async (shareId: string) => {
      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair) {
        p.setError('No keypair available');
        return;
      }

      const shareItem = p.sharedItems.find((s) => s.share.shareId === shareId);
      if (!shareItem) return;

      const share = shareItem.share;

      p.setIsLoading(true);
      p.setError(null);
      p.clearPolling();

      try {
        const itemKey = await unwrapKey(
          hexToBytes(share.encryptedKey),
          auth.vaultKeypair.privateKey,
        );

        if (share.itemType === 'folder') {
          let folderKeyStored = false;
          try {
            const resolved = await resolveIpnsRecord(share.ipnsName);
            if (!resolved) throw new Error('Could not resolve shared folder IPNS');

            const encryptedBytes = await fetchFromIpfs(resolved.cid);
            const encryptedJson = new TextDecoder().decode(encryptedBytes);
            const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
            const metadata = await decryptFolderMetadata(encrypted, itemKey);

            if (share.permission === 'write' && share.encryptedIpnsKey) {
              try {
                const ipnsPrivKey = await unwrapKey(
                  hexToBytes(share.encryptedIpnsKey),
                  auth.vaultKeypair.privateKey,
                );
                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
              } catch (err) {
                logger.error('[SharedNav] Failed to unwrap IPNS key for write share:', err);
              }
            }

            const children = metadata.children ?? [];
            const seqNum = BigInt(resolved.sequenceNumber);
            p.setCurrentView('folder');
            p.setCurrentShareId(shareId);
            p.setFolderChildren(children);
            p.folderChildrenRef.current = children;
            p.setFolderKey(itemKey);
            folderKeyStored = true;
            p.setBreadcrumbs([{ id: shareId, name: share.itemName }]);
            p.setPermission(p.ipnsPrivateKeyRef.current ? share.permission : 'read');
            p.setIpnsName(share.ipnsName);
            p.setCurrentSequenceNumber(seqNum);
            p.sequenceNumberRef.current = seqNum;
            p.navStackRef.current = [];
          } finally {
            if (!folderKeyStored) itemKey.fill(0);
          }
        } else {
          let folderKeyStored = false;
          try {
            if (share.permission === 'write' && share.encryptedIpnsKey) {
              try {
                const ipnsPrivKey = await unwrapKey(
                  hexToBytes(share.encryptedIpnsKey),
                  auth.vaultKeypair.privateKey,
                );
                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
              } catch (err) {
                logger.error('[SharedNav] Failed to unwrap IPNS key for write file share:', err);
              }
            }
            p.setCurrentView('file');
            p.setCurrentShareId(shareId);
            p.setFolderKey(itemKey);
            folderKeyStored = true;
            p.setPermission(p.ipnsPrivateKeyRef.current ? share.permission : 'read');
            p.setIpnsName(share.ipnsName);
            p.setBreadcrumbs([{ id: shareId, name: share.itemName }]);
          } finally {
            if (!folderKeyStored) itemKey.fill(0);
          }
        }
      } catch (err) {
        logger.error('[SharedNav] Failed to navigate to shared item:', err);
        p.setError('Failed to open shared item');
      } finally {
        p.setIsLoading(false);
      }
    },
    [p.sharedItems, p.clearPolling],
  );

  /**
   * Navigate into a subfolder within a shared folder.
   */
  const navigateToSubfolder = useCallback(
    async (folderId: string, folderName: string) => {
      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair || !p.currentShareId) return;

      p.setIsLoading(true);
      p.setError(null);
      p.clearPolling();

      try {
        const keys = await p.getShareKeys(p.currentShareId);
        const keyRecord = keys.find((k) => k.keyType === 'folder' && k.itemId === folderId);
        if (!keyRecord) throw new Error('No key available for this subfolder');

        const subfolderKey = await unwrapKey(
          hexToBytes(keyRecord.encryptedKey),
          auth.vaultKeypair.privateKey,
        );
        let subfolderKeyStored = false;

        try {
          const folderEntry = p.folderChildren.find(
            (c): c is FolderEntry => c.type === 'folder' && c.id === folderId,
          );
          if (!folderEntry) throw new Error('Subfolder not found in current children');

          const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
          if (!resolved) throw new Error('Could not resolve subfolder IPNS');

          const encryptedBytes = await fetchFromIpfs(resolved.cid);
          const encryptedJson = new TextDecoder().decode(encryptedBytes);
          const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
          const metadata = await decryptFolderMetadata(encrypted, subfolderKey);

          if (p.folderKey && p.ipnsName) {
            p.navStackRef.current.push({
              folderId: p.breadcrumbs[p.breadcrumbs.length - 1]?.id ?? '',
              folderName: p.breadcrumbs[p.breadcrumbs.length - 1]?.name ?? '',
              children: p.folderChildren,
              folderKey: p.folderKey,
              ipnsName: p.ipnsName,
              sequenceNumber: p.currentSequenceNumber,
            });
          }

          const children = metadata.children ?? [];
          const seqNum = BigInt(resolved.sequenceNumber);
          p.setFolderChildren(children);
          p.folderChildrenRef.current = children;
          p.setFolderKey(subfolderKey);
          subfolderKeyStored = true;
          p.setBreadcrumbs((prev) => [...prev, { id: folderId, name: folderName }]);
          p.setIpnsName(folderEntry.ipnsName);
          p.setCurrentSequenceNumber(seqNum);
          p.sequenceNumberRef.current = seqNum;

          if (p.permission === 'write' && p.currentShareId) {
            p.zeroIpnsKey();
            let restored = false;
            try {
              const subKeys = await p.getShareKeys(p.currentShareId);
              const ipnsKeyRecord = subKeys.find(
                (k) => k.keyType === 'folder-ipns' && k.itemId === folderId,
              );
              if (ipnsKeyRecord) {
                const ipnsPrivKey = await unwrapKey(
                  hexToBytes(ipnsKeyRecord.encryptedKey),
                  auth.vaultKeypair.privateKey,
                );
                p.ipnsPrivateKeyRef.current = ipnsPrivKey;
                restored = true;
              }
            } catch {
              // Couldn't get subfolder IPNS key
            }
            if (!restored) p.setPermission('read');
          }
        } finally {
          if (!subfolderKeyStored) subfolderKey.fill(0);
        }
      } catch (err) {
        logger.error('[SharedNav] Failed to navigate to subfolder:', err);
        p.setError('Failed to open subfolder');
      } finally {
        p.setIsLoading(false);
      }
    },
    [
      p.currentShareId,
      p.folderChildren,
      p.folderKey,
      p.breadcrumbs,
      p.getShareKeys,
      p.ipnsName,
      p.currentSequenceNumber,
      p.clearPolling,
      p.permission,
      p.zeroIpnsKey,
    ],
  );

  /**
   * Navigate back to the top-level shared list.
   */
  const navigateToRoot = useCallback(() => {
    if (p.folderKey) p.folderKey.fill(0);
    for (const entry of p.navStackRef.current) {
      entry.folderKey.fill(0);
    }
    p.zeroIpnsKey();
    p.clearPolling();
    p.setCurrentView('list');
    p.setCurrentShareId(null);
    p.setFolderChildren([]);
    p.setFolderKey(null);
    p.setBreadcrumbs([]);
    p.setPermission(null);
    p.setIpnsName(null);
    p.setCurrentSequenceNumber(null);
    p.navStackRef.current = [];
    p.setError(null);
  }, [p.folderKey, p.zeroIpnsKey, p.clearPolling]);

  /**
   * Restore the correct IPNS private key for the current depth.
   */
  const restoreIpnsKeyForDepth = useCallback(
    async (targetFolderId?: string) => {
      if (!p.currentShareId) return;
      const shareItem = p.sharedItems.find((s) => s.share.shareId === p.currentShareId);
      const share = shareItem?.share;
      if (share?.permission !== 'write') return;

      p.zeroIpnsKey();
      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair) return;

      try {
        if (!targetFolderId && share.encryptedIpnsKey) {
          const ipnsPrivKey = await unwrapKey(
            hexToBytes(share.encryptedIpnsKey),
            auth.vaultKeypair.privateKey,
          );
          p.ipnsPrivateKeyRef.current = ipnsPrivKey;
          p.setPermission('write');
        } else if (targetFolderId) {
          const keys = await p.getShareKeys(p.currentShareId);
          const ipnsKeyRecord = keys.find(
            (k) => k.keyType === 'folder-ipns' && k.itemId === targetFolderId,
          );
          if (ipnsKeyRecord) {
            const ipnsPrivKey = await unwrapKey(
              hexToBytes(ipnsKeyRecord.encryptedKey),
              auth.vaultKeypair.privateKey,
            );
            p.ipnsPrivateKeyRef.current = ipnsPrivKey;
            p.setPermission('write');
          } else {
            p.setPermission('read');
          }
        }
      } catch {
        // Couldn't restore — stay read-only
      }
    },
    [p.currentShareId, p.getShareKeys, p.sharedItems, p.zeroIpnsKey],
  );

  /**
   * Navigate up one level.
   */
  const navigateUp = useCallback(async () => {
    if (p.navStackRef.current.length > 0) {
      if (p.folderKey) p.folderKey.fill(0);
      const prev = p.navStackRef.current.pop()!;
      p.setFolderChildren(prev.children);
      p.folderChildrenRef.current = prev.children;
      p.setFolderKey(prev.folderKey);
      p.setBreadcrumbs((crumbs) => crumbs.slice(0, -1));
      p.setIpnsName(prev.ipnsName);
      p.setCurrentSequenceNumber(prev.sequenceNumber);
      p.sequenceNumberRef.current = prev.sequenceNumber;

      if (p.navStackRef.current.length === 0) {
        await restoreIpnsKeyForDepth();
      } else {
        await restoreIpnsKeyForDepth(prev.folderId);
      }
    } else if (p.currentView === 'folder' || p.currentView === 'file') {
      navigateToRoot();
    }
  }, [p.currentView, p.folderKey, navigateToRoot, restoreIpnsKeyForDepth]);

  /**
   * Navigate directly to a breadcrumb level.
   */
  const navigateToBreadcrumb = useCallback(
    async (crumbIndex: number) => {
      const popsNeeded = p.breadcrumbs.length - 1 - crumbIndex;
      if (popsNeeded <= 0) return;
      if (p.folderKey) p.folderKey.fill(0);
      for (let i = 0; i < popsNeeded - 1; i++) {
        const entry = p.navStackRef.current.pop();
        if (entry) entry.folderKey.fill(0);
      }
      const target = p.navStackRef.current.pop();
      if (target) {
        p.setFolderChildren(target.children);
        p.folderChildrenRef.current = target.children;
        p.setFolderKey(target.folderKey);
        p.setBreadcrumbs((crumbs) => crumbs.slice(0, crumbIndex + 1));
        p.setIpnsName(target.ipnsName);
        p.setCurrentSequenceNumber(target.sequenceNumber);
        p.sequenceNumberRef.current = target.sequenceNumber;

        if (p.navStackRef.current.length === 0) {
          await restoreIpnsKeyForDepth();
        } else {
          await restoreIpnsKeyForDepth(target.folderId);
        }
      }
    },
    [p.breadcrumbs, p.folderKey, restoreIpnsKeyForDepth],
  );

  /**
   * Download a shared file using re-wrapped file keys.
   */
  const downloadSharedFile = useCallback(
    async (item: FilePointer) => {
      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair || !p.currentShareId || !p.folderKey) return;

      const downloadStore = useDownloadStore.getState();

      try {
        downloadStore.startDownload(item.name);

        const keys = await p.getShareKeys(p.currentShareId);

        const resolved = await resolveIpnsRecord(item.fileMetaIpnsName);
        if (!resolved) throw new Error('File metadata IPNS not found');

        const encryptedBytes = await fetchFromIpfs(resolved.cid);
        const encryptedJson = new TextDecoder().decode(encryptedBytes);
        const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
        const fileMeta = await decryptFileMetadata(encrypted, p.folderKey);

        const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
        if (!fileKeyRecord) {
          throw new Error('File key not available — the folder owner may need to re-share');
        }
        const wrappedKey = fileKeyRecord.encryptedKey;

        const plaintext = await downloadFile(
          {
            cid: fileMeta.cid,
            iv: fileMeta.fileIv,
            wrappedKey,
            originalName: item.name,
            encryptionMode: fileMeta.encryptionMode,
          },
          auth.vaultKeypair.privateKey,
        );

        downloadStore.setDecrypting();
        triggerBrowserDownload(plaintext, item.name);
        downloadStore.setSuccess();
      } catch (err) {
        const message = (err as Error).message || 'Download failed';
        downloadStore.setError(message);
        logger.error('[SharedNav] Shared file download failed:', err);
      }
    },
    [p.currentShareId, p.folderKey, p.getShareKeys],
  );

  /**
   * Hide a shared item from the user's view.
   */
  const hideSharedItem = useCallback(async (shareId: string) => {
    try {
      await hideShare(shareId);
      useShareStore.getState().removeReceivedShare(shareId);
      p.setSharedItems((prev) => prev.filter((s) => s.share.shareId !== shareId));
    } catch (err) {
      logger.error('[SharedNav] Failed to hide share:', err);
      p.setError('Failed to hide shared item');
    }
  }, []);

  return {
    navigateToShare,
    navigateToSubfolder,
    navigateUp,
    navigateToRoot,
    navigateToBreadcrumb,
    downloadSharedFile,
    hideSharedItem,
  };
}

/**
 * useSharedWriteOps -- Write operation handlers for shared folders.
 *
 * Extracted from useSharedNavigation.ts to separate write concerns
 * from navigation. Takes navigation state as params.
 */

import { useCallback, type MutableRefObject } from 'react';
import type { FolderChild, FilePointer } from '@cipherbox/core';
import { unwrapKey, hexToBytes } from '@cipherbox/crypto';
import {
  uploadToSharedFolder,
  createSharedSubfolder,
  renameInSharedFolder,
  deleteFromSharedFolder,
  updateSharedFile,
  type SharedWriteContext,
  withRevocationGuard as sdkWithRevocationGuard,
  ShareKeyCache,
  buildSharedWriteContext,
} from '@cipherbox/sdk';
import { withConflictRetry } from './folder-helpers';
import { useAuthStore } from '../stores/auth.store';
import { fetchShareKeys, addShareKeys } from '../services/share.service';
import { apiAxios, apiUrl } from '../lib/api-config';
import { logger } from '../lib/logger';
import type { SharedListItem } from './useSharedNavigation';

/** Parse a 0x-prefixed or bare hex public key string into bytes. */
function parsePublicKey(keyHex: string): Uint8Array {
  const hex = keyHex.startsWith('0x') ? keyHex.slice(2) : keyHex;
  return hexToBytes(hex);
}

export type SharedWriteOpsParams = {
  currentShareId: string | null;
  folderKey: Uint8Array | null;
  ipnsName: string | null;
  currentSequenceNumber: bigint | null;
  sharedItems: SharedListItem[];
  folderChildrenRef: MutableRefObject<FolderChild[]>;
  sequenceNumberRef: MutableRefObject<bigint | null>;
  ipnsPrivateKeyRef: MutableRefObject<Uint8Array | null>;
  shareKeysCacheRef: MutableRefObject<ShareKeyCache>;
  setFolderChildren: (children: FolderChild[]) => void;
  setCurrentSequenceNumber: (seq: bigint | null) => void;
  setPermission: (perm: 'read' | 'write' | null) => void;
  setIsLoading: (loading: boolean) => void;
  setError: (error: string | null) => void;
  refreshFolderContents: (ipnsName: string, folderKey: Uint8Array) => Promise<FolderChild[] | null>;
  handleRevocation: (silent: boolean) => void;
};

export function useSharedWriteOps(p: SharedWriteOpsParams) {
  /**
   * Re-sync the current shared folder for conflict retry.
   */
  const resyncSharedFolder = useCallback(async () => {
    if (!p.ipnsName || !p.folderKey) return;
    await p.refreshFolderContents(p.ipnsName, p.folderKey);
  }, [p.ipnsName, p.folderKey, p.refreshFolderContents]);

  /**
   * Build SharedWriteContext for SDK shared-write operations.
   * Returns null if any required state is missing.
   */
  const buildSharedWriteCtx = useCallback((): SharedWriteContext | null => {
    const currentIpnsKey = p.ipnsPrivateKeyRef.current;
    const auth = useAuthStore.getState();
    if (
      !currentIpnsKey ||
      !p.folderKey ||
      !p.ipnsName ||
      p.currentSequenceNumber === null ||
      !auth.vaultKeypair
    )
      return null;

    const shareItem = p.sharedItems.find((s) => s.share.shareId === p.currentShareId);
    if (!shareItem) return null;
    const ownerPubKey = parsePublicKey(shareItem.share.sharerPublicKey);

    return buildSharedWriteContext({
      ctx: {
        apiUrl,
        getAccessToken: async () => useAuthStore.getState().accessToken || '',
        axiosInstance: apiAxios,
      },
      folderKey: p.folderKey,
      ipnsPrivateKey: currentIpnsKey,
      ipnsName: p.ipnsName,
      sequenceNumber: p.currentSequenceNumber,
      children: p.folderChildrenRef.current,
      ownerPublicKey: ownerPubKey,
      recipientPublicKey: auth.vaultKeypair.publicKey,
      shareId: p.currentShareId!,
      addShareKeysFn: async (sid, keys) => {
        await addShareKeys(sid, keys);
        p.shareKeysCacheRef.current.invalidate(sid);
      },
    });
  }, [p.folderKey, p.ipnsName, p.currentSequenceNumber, p.currentShareId, p.sharedItems]);

  /**
   * Wrap a write operation with 403 revocation detection.
   */
  const withRevocationGuard = useCallback(
    async <T>(operation: () => Promise<T>): Promise<T> => {
      return sdkWithRevocationGuard(operation, () => p.handleRevocation(true));
    },
    [p.handleRevocation],
  );

  /**
   * Upload a file to the currently-viewed write-shared folder.
   */
  const uploadFileHandler = useCallback(
    async (file: File) => {
      const swCtx = buildSharedWriteCtx();
      if (!swCtx) {
        p.setError('Write access not available');
        return;
      }

      p.setIsLoading(true);
      p.setError(null);

      try {
        await withRevocationGuard(async () => {
          const data = new Uint8Array(await file.arrayBuffer());

          await withConflictRetry(
            async () => {
              const freshCtx = {
                ...swCtx,
                children: p.folderChildrenRef.current,
                sequenceNumber: p.sequenceNumberRef.current ?? 0n,
              };
              const result = await uploadToSharedFolder(freshCtx, {
                data,
                fileName: file.name,
                mimeType: file.type || undefined,
              });
              p.sequenceNumberRef.current = result.newSequenceNumber;
              p.folderChildrenRef.current = result.updatedChildren;
              p.setCurrentSequenceNumber(result.newSequenceNumber);
              p.setFolderChildren(result.updatedChildren);
            },
            async () => {
              await resyncSharedFolder();
            },
          );
        });
      } catch (err) {
        const message = (err as Error).message || 'Upload failed';
        if (!message.includes('write access revoked')) {
          p.setError(message);
        }
        logger.error('[SharedNav] Shared folder upload failed:', err);
      } finally {
        p.setIsLoading(false);
      }
    },
    [buildSharedWriteCtx, resyncSharedFolder, withRevocationGuard],
  );

  /**
   * Create a subfolder in the currently-viewed write-shared folder.
   */
  const createFolderHandler = useCallback(
    async (name: string) => {
      const swCtx = buildSharedWriteCtx();
      if (!swCtx) {
        p.setError('Write access not available');
        return;
      }

      p.setIsLoading(true);
      p.setError(null);

      try {
        await withRevocationGuard(async () => {
          await withConflictRetry(
            async () => {
              const freshCtx = {
                ...swCtx,
                children: p.folderChildrenRef.current,
                sequenceNumber: p.sequenceNumberRef.current ?? 0n,
              };
              const result = await createSharedSubfolder(freshCtx, { name });
              p.sequenceNumberRef.current = result.newSequenceNumber;
              p.folderChildrenRef.current = result.updatedChildren;
              p.setCurrentSequenceNumber(result.newSequenceNumber);
              p.setFolderChildren(result.updatedChildren);
            },
            async () => {
              await resyncSharedFolder();
            },
          );
        });
      } catch (err) {
        const message = (err as Error).message || 'Failed to create folder';
        if (!message.includes('write access revoked')) {
          p.setError(message);
        }
        logger.error('[SharedNav] Shared folder create failed:', err);
      } finally {
        p.setIsLoading(false);
      }
    },
    [buildSharedWriteCtx, resyncSharedFolder, withRevocationGuard],
  );

  /**
   * Rename an item in the currently-viewed write-shared folder.
   */
  const renameItemHandler = useCallback(
    async (item: FolderChild, newName: string) => {
      const swCtx = buildSharedWriteCtx();
      if (!swCtx) {
        p.setError('Write access not available');
        return;
      }

      p.setIsLoading(true);
      p.setError(null);

      try {
        await withRevocationGuard(async () => {
          await withConflictRetry(
            async () => {
              const freshCtx = {
                ...swCtx,
                children: p.folderChildrenRef.current,
                sequenceNumber: p.sequenceNumberRef.current ?? 0n,
              };
              const result = await renameInSharedFolder(freshCtx, { itemId: item.id, newName });
              p.sequenceNumberRef.current = result.newSequenceNumber;
              p.folderChildrenRef.current = result.updatedChildren;
              p.setCurrentSequenceNumber(result.newSequenceNumber);
              p.setFolderChildren(result.updatedChildren);
            },
            async () => {
              await resyncSharedFolder();
            },
          );
        });
      } catch (err) {
        const message = (err as Error).message || 'Failed to rename';
        if (!message.includes('write access revoked')) {
          p.setError(message);
        }
        logger.error('[SharedNav] Shared folder rename failed:', err);
      } finally {
        p.setIsLoading(false);
      }
    },
    [buildSharedWriteCtx, resyncSharedFolder, withRevocationGuard],
  );

  /**
   * Update a file's content in the currently-viewed write-shared folder.
   */
  const updateSharedFileHandler = useCallback(
    async (item: FilePointer, newContent: Uint8Array): Promise<void> => {
      if (!p.folderKey) throw new Error('Folder key not available');

      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair) throw new Error('No keypair available');

      const shareItem = p.sharedItems.find((s) => s.share.shareId === p.currentShareId);
      if (!shareItem) throw new Error('Share not found');
      const ownerPublicKey = parsePublicKey(shareItem.share.sharerPublicKey);

      await withRevocationGuard(async () => {
        await updateSharedFile({
          ctx: {
            apiUrl,
            getAccessToken: async () => useAuthStore.getState().accessToken || '',
            axiosInstance: apiAxios,
          },
          folderKey: p.folderKey!,
          ownerPublicKey,
          recipientPublicKey: auth.vaultKeypair!.publicKey,
          shareId: p.currentShareId!,
          addShareKeysFn: async (sid, keys) => {
            await addShareKeys(sid, keys);
            p.shareKeysCacheRef.current.invalidate(sid);
          },
          filePointer: item,
          newContent,
          getFileIpnsKeyFn: async (itemId: string) => {
            const keys = await fetchShareKeys(p.currentShareId!);
            const exactMatch = keys.find((k) => k.keyType === 'file-ipns' && k.itemId === itemId);
            const ipnsKeyRecord =
              exactMatch ??
              (shareItem.share.itemType === 'file'
                ? keys.find((k) => k.keyType === 'file-ipns')
                : undefined);
            if (ipnsKeyRecord) {
              return unwrapKey(
                hexToBytes(ipnsKeyRecord.encryptedKey),
                auth.vaultKeypair!.privateKey,
              );
            }
            if (item.ipnsPrivateKeyEncrypted) {
              try {
                return await unwrapKey(
                  hexToBytes(item.ipnsPrivateKeyEncrypted),
                  auth.vaultKeypair!.privateKey,
                );
              } catch {
                return null;
              }
            }
            return null;
          },
        });
      });
    },
    [p.folderKey, p.currentShareId, p.sharedItems, withRevocationGuard],
  );

  /**
   * Delete an item from the currently-viewed write-shared folder.
   */
  const deleteItemHandler = useCallback(
    async (item: FolderChild) => {
      const swCtx = buildSharedWriteCtx();
      if (!swCtx) {
        p.setError('Write access not available');
        return;
      }

      p.setIsLoading(true);
      p.setError(null);

      try {
        await withRevocationGuard(async () => {
          await withConflictRetry(
            async () => {
              const freshCtx = {
                ...swCtx,
                children: p.folderChildrenRef.current,
                sequenceNumber: p.sequenceNumberRef.current ?? 0n,
              };
              const result = await deleteFromSharedFolder(freshCtx, { itemId: item.id });
              p.sequenceNumberRef.current = result.newSequenceNumber;
              p.folderChildrenRef.current = result.updatedChildren;
              p.setCurrentSequenceNumber(result.newSequenceNumber);
              p.setFolderChildren(result.updatedChildren);
            },
            async () => {
              await resyncSharedFolder();
            },
          );
        });
      } catch (err) {
        const message = (err as Error).message || 'Failed to delete';
        if (!message.includes('write access revoked')) {
          p.setError(message);
        }
        logger.error('[SharedNav] Shared folder delete failed:', err);
      } finally {
        p.setIsLoading(false);
      }
    },
    [buildSharedWriteCtx, resyncSharedFolder, withRevocationGuard],
  );

  return {
    uploadFile: uploadFileHandler,
    createFolder: createFolderHandler,
    renameItem: renameItemHandler,
    deleteItem: deleteItemHandler,
    updateSharedFile: updateSharedFileHandler,
  };
}

/**
 * useFileBrowserActions -- Handler logic for FileBrowser.
 *
 * Extracted from FileBrowser.tsx to separate handler logic from JSX.
 * Contains all useCallback handlers, dialog state, selection state,
 * and drag state management.
 */

import {
  useState,
  useCallback,
  useEffect,
  useRef,
  useMemo,
  type DragEvent,
  type MouseEvent,
} from 'react';
import type { FolderChild } from '@cipherbox/core';
import { useDialogState } from '../../hooks/useDialogState';
import {
  isFilePointer,
  isImageFile,
  isPdfFile,
  isAudioFile,
  isVideoFile,
} from '../../utils/fileTypes';
import { useFolderStore } from '../../stores/folder.store';
import { useSyncStore } from '../../stores/sync.store';
import { isExternalFileDrag } from '../../hooks/useDropUpload';
import { resolveIpnsRecord } from '../../services/ipns.service';
import { fetchAndDecryptMetadata } from '../../services/folder.service';
import { triggerSearchIndexRebuild } from '../../hooks/useSearch';
import { logger } from '../../lib/logger';

export type FileBrowserActionsParams = {
  currentFolderId: string;
  currentFolder: {
    children: FolderChild[];
    folderKey: Uint8Array;
  } | null;
  breadcrumbs: Array<{ id: string; name: string }>;
  navigateTo: (folderId: string) => void;
  navigateUp: () => void;
  createFolder: (name: string, parentFolderId: string | null) => Promise<{ ipnsName: string }>;
  renameItem: (
    itemId: string,
    itemType: 'file' | 'folder',
    newName: string,
    parentId: string,
  ) => Promise<void>;
  moveItem: (
    itemId: string,
    itemType: 'file' | 'folder',
    sourceParentId: string,
    destParentId: string,
  ) => Promise<void>;
  moveItems: (
    items: Array<{ id: string; type: 'file' | 'folder' }>,
    sourceParentId: string,
    destParentId: string,
  ) => Promise<void>;
  deleteItem: (itemId: string, itemType: 'file' | 'folder', parentId: string) => Promise<void>;
  deleteItems: (
    items: Array<{ id: string; type: 'file' | 'folder' }>,
    parentId: string,
  ) => Promise<void>;
  isOperating: boolean;
  isDownloading: boolean;
  downloadFromIpns: (params: {
    fileMetaIpnsName: string;
    folderKey: Uint8Array;
    fileName: string;
  }) => Promise<void>;
  handleFileDrop: (files: File[], folderId: string) => void;
  contextMenu: {
    visible: boolean;
    x: number;
    y: number;
    item: FolderChild | null;
    show: (event: MouseEvent, item: FolderChild) => void;
    hide: () => void;
  };
  rootIpnsName: string | null;
};

export function useFileBrowserActions(params: FileBrowserActionsParams) {
  const {
    currentFolderId,
    currentFolder,
    navigateTo,
    createFolder,
    renameItem,
    moveItem,
    moveItems,
    deleteItem,
    deleteItems,
    downloadFromIpns,
    handleFileDrop,
    contextMenu,
    rootIpnsName,
  } = params;

  const children = currentFolder?.children ?? [];

  // ---------------------------------------------------------------------------
  // Sync callback
  // ---------------------------------------------------------------------------

  const handleSync = useCallback(async () => {
    if (!rootIpnsName) return;

    const resolved = await resolveIpnsRecord(rootIpnsName);
    if (!resolved) return;

    const rootFolder = useFolderStore.getState().folders['root'];
    if (!rootFolder) return;

    if (resolved.sequenceNumber <= rootFolder.sequenceNumber) return;

    try {
      const metadata = await fetchAndDecryptMetadata(resolved.cid, rootFolder.folderKey);
      useFolderStore.getState().updateFolderChildren('root', metadata.children);
      useFolderStore.getState().updateFolderSequence('root', resolved.sequenceNumber);
      triggerSearchIndexRebuild();
    } catch (err) {
      logger.error('[FileBrowser] Sync refresh failed:', err);
      if (!useSyncStore.getState().initialSyncComplete) {
        throw err;
      }
    }
  }, [rootIpnsName]);

  // ---------------------------------------------------------------------------
  // Drag state
  // ---------------------------------------------------------------------------

  const [isDraggingExternal, setIsDraggingExternal] = useState(false);
  const dragCounterRef = useRef(0);

  const handleContentDragEnter = useCallback((e: DragEvent) => {
    if (isExternalFileDrag(e.dataTransfer)) {
      dragCounterRef.current += 1;
      if (dragCounterRef.current === 1) {
        setIsDraggingExternal(true);
      }
    }
  }, []);

  const handleContentDragOver = useCallback((e: DragEvent) => {
    if (isExternalFileDrag(e.dataTransfer)) {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'copy';
    }
  }, []);

  const handleContentDragLeave = useCallback((e: DragEvent) => {
    if (isExternalFileDrag(e.dataTransfer)) {
      dragCounterRef.current -= 1;
      if (dragCounterRef.current <= 0) {
        dragCounterRef.current = 0;
        setIsDraggingExternal(false);
      }
    }
  }, []);

  useEffect(() => {
    const resetDragState = () => {
      dragCounterRef.current = 0;
      setIsDraggingExternal(false);
    };
    const handleWindowDrop = (e: Event) => {
      e.preventDefault();
      resetDragState();
    };
    const handleWindowDragLeave = (e: globalThis.DragEvent) => {
      if (!e.relatedTarget) resetDragState();
    };
    window.addEventListener('dragend', resetDragState);
    window.addEventListener('drop', handleWindowDrop);
    window.addEventListener('dragleave', handleWindowDragLeave as EventListener);
    return () => {
      window.removeEventListener('dragend', resetDragState);
      window.removeEventListener('drop', handleWindowDrop);
      window.removeEventListener('dragleave', handleWindowDragLeave as EventListener);
    };
  }, []);

  const handleContentDrop = useCallback(
    (e: DragEvent) => {
      dragCounterRef.current = 0;
      setIsDraggingExternal(false);
      if (!e.dataTransfer.files || e.dataTransfer.files.length === 0) return;
      if (!isExternalFileDrag(e.dataTransfer)) return;
      e.preventDefault();
      const files = Array.from(e.dataTransfer.files);
      handleFileDrop(files, currentFolderId);
    },
    [handleFileDrop, currentFolderId],
  );

  const handleExternalFileDrop = useCallback(
    (files: File[], targetFolderId: string) => {
      dragCounterRef.current = 0;
      setIsDraggingExternal(false);
      handleFileDrop(files, targetFolderId);
    },
    [handleFileDrop],
  );

  // ---------------------------------------------------------------------------
  // Selection state
  // ---------------------------------------------------------------------------

  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const lastSelectedIdRef = useRef<string | null>(null);

  const childIds = useMemo(() => new Set(children.map((c) => c.id)), [children]);
  useEffect(() => {
    setSelectedIds((prev) => {
      if (prev.size === 0) return prev;
      const pruned = new Set([...prev].filter((id) => childIds.has(id)));
      if (pruned.size === prev.size) return prev;
      return pruned;
    });
  }, [childIds]);

  const selectedItems = useMemo(
    () => children.filter((c) => selectedIds.has(c.id)),
    [children, selectedIds],
  );
  const multiSelectActive = selectedIds.size > 0;

  // ---------------------------------------------------------------------------
  // Dialog states
  // ---------------------------------------------------------------------------

  const [confirmDialog, openConfirmDialog, closeConfirmDialog] = useDialogState<FolderChild>();
  const [renameDialog, openRenameDialog, closeRenameDialog] = useDialogState<FolderChild>();
  const [moveDialog, openMoveDialog, closeMoveDialog] = useDialogState<FolderChild>();
  const [detailsDialog, openDetailsDialog, closeDetailsDialog] = useDialogState<FolderChild>();
  const [editorDialog, openEditorDialog, closeEditorDialog] = useDialogState<FolderChild>();
  const [imagePreviewDialog, openImagePreviewDialog, closeImagePreviewDialog] =
    useDialogState<FolderChild>();
  const [pdfPreviewDialog, openPdfPreviewDialog, closePdfPreviewDialog] =
    useDialogState<FolderChild>();
  const [audioPlayerDialog, openAudioPlayerDialog, closeAudioPlayerDialog] =
    useDialogState<FolderChild>();
  const [videoPlayerDialog, openVideoPlayerDialog, closeVideoPlayerDialog] =
    useDialogState<FolderChild>();
  const [createFolderDialogOpen, setCreateFolderDialogOpen] = useState(false);
  const [shareItem, setShareItem] = useState<FolderChild | null>(null);

  const [batchDeleteDialog, setBatchDeleteDialog] = useState<{
    open: boolean;
    items: FolderChild[];
  }>({ open: false, items: [] });

  const [batchMoveDialog, setBatchMoveDialog] = useState<{
    open: boolean;
    items: FolderChild[];
  }>({ open: false, items: [] });

  // ---------------------------------------------------------------------------
  // Handler callbacks
  // ---------------------------------------------------------------------------

  const handleNavigate = useCallback(
    (folderId: string) => {
      setSelectedIds(new Set());
      lastSelectedIdRef.current = null;
      navigateTo(folderId);
    },
    [navigateTo],
  );

  const handleSelect = useCallback(
    (itemId: string, event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }) => {
      const isCtrl = event.ctrlKey || event.metaKey;
      const isShift = event.shiftKey;

      if (isShift && lastSelectedIdRef.current) {
        const sortedChildren = [...children].sort((a, b) => {
          if (a.type === 'folder' && b.type !== 'folder') return -1;
          if (a.type !== 'folder' && b.type === 'folder') return 1;
          return a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
        });
        const ids = sortedChildren.map((c) => c.id);
        const startIdx = ids.indexOf(lastSelectedIdRef.current);
        const endIdx = ids.indexOf(itemId);
        if (startIdx !== -1 && endIdx !== -1) {
          const rangeStart = Math.min(startIdx, endIdx);
          const rangeEnd = Math.max(startIdx, endIdx);
          const rangeIds = ids.slice(rangeStart, rangeEnd + 1);
          setSelectedIds((prev) => {
            const next = new Set(prev);
            for (const id of rangeIds) next.add(id);
            return next;
          });
        }
      } else if (isCtrl) {
        setSelectedIds((prev) => {
          const next = new Set(prev);
          if (next.has(itemId)) next.delete(itemId);
          else next.add(itemId);
          return next;
        });
        lastSelectedIdRef.current = itemId;
      } else {
        setSelectedIds(new Set([itemId]));
        lastSelectedIdRef.current = itemId;
      }
    },
    [children],
  );

  const handleSelectAll = useCallback(() => {
    if (selectedIds.size === children.length) {
      setSelectedIds(new Set());
      lastSelectedIdRef.current = null;
    } else {
      setSelectedIds(new Set(children.map((c) => c.id)));
    }
  }, [children, selectedIds.size]);

  const clearSelection = useCallback(() => {
    setSelectedIds(new Set());
    lastSelectedIdRef.current = null;
  }, []);

  const handleContextMenu = useCallback(
    (event: MouseEvent, item: FolderChild) => {
      if (!selectedIds.has(item.id)) {
        setSelectedIds(new Set([item.id]));
        lastSelectedIdRef.current = item.id;
      }
      contextMenu.show(event, item);
    },
    [contextMenu, selectedIds],
  );

  const handleDragStart = useCallback((_event: DragEvent, _item: FolderChild) => {
    // Drag data set by FileListItem
  }, []);

  const handleDropOnFolder = useCallback(
    async (
      items: Array<{ id: string; type: 'file' | 'folder' }>,
      sourceParentId: string,
      destFolderId: string,
    ) => {
      try {
        if (items.length === 1) {
          await moveItem(items[0].id, items[0].type, sourceParentId, destFolderId);
        } else {
          await moveItems(items, sourceParentId, destFolderId);
          clearSelection();
        }
      } catch (err) {
        logger.error('[FileBrowser] Move failed:', err);
      }
    },
    [moveItem, moveItems, clearSelection],
  );

  const handleDownload = useCallback(async () => {
    const item = contextMenu.item;
    if (!item || !isFilePointer(item)) return;
    const folderKey = currentFolder?.folderKey;
    if (!folderKey) return;
    try {
      await downloadFromIpns({
        fileMetaIpnsName: item.fileMetaIpnsName,
        folderKey,
        fileName: item.name,
      });
    } catch (err) {
      logger.error('[FileBrowser] Download failed:', err);
    }
  }, [contextMenu.item, downloadFromIpns, currentFolder?.folderKey]);

  const handleRenameClick = useCallback(() => {
    if (contextMenu.item) openRenameDialog(contextMenu.item);
  }, [contextMenu.item, openRenameDialog]);

  const handleDeleteClick = useCallback(() => {
    if (contextMenu.item) openConfirmDialog(contextMenu.item);
  }, [contextMenu.item, openConfirmDialog]);

  const handleMoveClick = useCallback(() => {
    if (contextMenu.item) openMoveDialog(contextMenu.item);
  }, [contextMenu.item, openMoveDialog]);

  const handleDetailsClick = useCallback(() => {
    if (contextMenu.item) openDetailsDialog(contextMenu.item);
  }, [contextMenu.item, openDetailsDialog]);

  const handleShareClick = useCallback(() => {
    if (contextMenu.item) setShareItem(contextMenu.item);
  }, [contextMenu.item]);

  const handleEditClick = useCallback(() => {
    if (contextMenu.item) openEditorDialog(contextMenu.item);
  }, [contextMenu.item, openEditorDialog]);

  const handlePreviewClick = useCallback(() => {
    const item = contextMenu.item;
    if (!item || !isFilePointer(item)) return;
    const name = item.name;
    if (isImageFile(name)) openImagePreviewDialog(item);
    else if (isPdfFile(name)) openPdfPreviewDialog(item);
    else if (isAudioFile(name)) openAudioPlayerDialog(item);
    else if (isVideoFile(name)) openVideoPlayerDialog(item);
  }, [
    contextMenu.item,
    openImagePreviewDialog,
    openPdfPreviewDialog,
    openAudioPlayerDialog,
    openVideoPlayerDialog,
  ]);

  const handleBatchDeleteClick = useCallback(() => {
    if (selectedItems.length === 0) return;
    setBatchDeleteDialog({ open: true, items: [...selectedItems] });
  }, [selectedItems]);

  const handleBatchMoveClick = useCallback(() => {
    if (selectedItems.length === 0) return;
    setBatchMoveDialog({ open: true, items: [...selectedItems] });
  }, [selectedItems]);

  const handleBatchDownload = useCallback(async () => {
    const files = selectedItems.filter(isFilePointer);
    if (files.length === 0) return;
    const folderKey = currentFolder?.folderKey;
    if (!folderKey) return;
    for (const file of files) {
      try {
        await downloadFromIpns({
          fileMetaIpnsName: file.fileMetaIpnsName,
          folderKey,
          fileName: file.name,
        });
      } catch (err) {
        logger.error('[FileBrowser] Batch download item failed:', err);
      }
    }
  }, [selectedItems, downloadFromIpns, currentFolder?.folderKey]);

  const handleBatchDeleteConfirm = useCallback(async () => {
    const items = batchDeleteDialog.items;
    if (items.length === 0) return;
    try {
      await deleteItems(
        items.map((i) => ({ id: i.id, type: i.type })),
        currentFolderId,
      );
      setBatchDeleteDialog({ open: false, items: [] });
      clearSelection();
    } catch (err) {
      logger.error('[FileBrowser] Batch delete failed:', err);
    }
  }, [batchDeleteDialog.items, deleteItems, currentFolderId, clearSelection]);

  const handleBatchMoveConfirm = useCallback(
    async (destinationFolderId: string) => {
      const items = batchMoveDialog.items;
      if (items.length === 0) return;
      try {
        await moveItems(
          items.map((i) => ({ id: i.id, type: i.type })),
          currentFolderId,
          destinationFolderId,
        );
        setBatchMoveDialog({ open: false, items: [] });
        clearSelection();
      } catch (err) {
        logger.error('[FileBrowser] Batch move failed:', err);
      }
    },
    [batchMoveDialog.items, moveItems, currentFolderId, clearSelection],
  );

  const closeBatchDeleteDialog = useCallback(() => {
    setBatchDeleteDialog({ open: false, items: [] });
  }, []);

  const closeBatchMoveDialog = useCallback(() => {
    setBatchMoveDialog({ open: false, items: [] });
  }, []);

  const handleRenameConfirm = useCallback(
    async (newName: string) => {
      const item = renameDialog.item;
      if (!item) return;
      try {
        await renameItem(item.id, item.type, newName, currentFolderId);
        closeRenameDialog();
      } catch (err) {
        logger.error('[FileBrowser] Rename failed:', err);
      }
    },
    [renameDialog.item, renameItem, currentFolderId, closeRenameDialog],
  );

  const handleDeleteConfirm = useCallback(async () => {
    const item = confirmDialog.item;
    if (!item) return;
    try {
      await deleteItem(item.id, item.type, currentFolderId);
      closeConfirmDialog();
    } catch (err) {
      logger.error('[FileBrowser] Delete failed:', err);
    }
  }, [confirmDialog.item, deleteItem, currentFolderId, closeConfirmDialog]);

  const handleMoveConfirm = useCallback(
    async (destinationFolderId: string) => {
      const item = moveDialog.item;
      if (!item) return;
      try {
        await moveItem(item.id, item.type, currentFolderId, destinationFolderId);
        closeMoveDialog();
      } catch (err) {
        logger.error('[FileBrowser] Move failed:', err);
      }
    },
    [moveDialog.item, moveItem, currentFolderId, closeMoveDialog],
  );

  const closeShareDialog = useCallback(() => {
    setShareItem(null);
  }, []);

  const openCreateFolderDialog = useCallback(() => {
    setCreateFolderDialogOpen(true);
  }, []);

  const closeCreateFolderDialog = useCallback(() => {
    setCreateFolderDialogOpen(false);
  }, []);

  const handleCreateFolderConfirm = useCallback(
    async (name: string) => {
      try {
        await createFolder(name, currentFolderId === 'root' ? null : currentFolderId);
      } catch (err) {
        logger.error('[FileBrowser] Create folder failed:', err);
      } finally {
        setCreateFolderDialogOpen(false);
      }
    },
    [createFolder, currentFolderId],
  );

  return {
    // Sync
    handleSync,
    // Drag
    isDraggingExternal,
    handleContentDragEnter,
    handleContentDragOver,
    handleContentDragLeave,
    handleContentDrop,
    handleExternalFileDrop,
    // Selection
    selectedIds,
    selectedItems,
    multiSelectActive,
    handleNavigate,
    handleSelect,
    handleSelectAll,
    clearSelection,
    // Context menu
    handleContextMenu,
    handleDragStart,
    handleDropOnFolder,
    // Item actions
    handleDownload,
    handleRenameClick,
    handleDeleteClick,
    handleMoveClick,
    handleDetailsClick,
    handleShareClick,
    handleEditClick,
    handlePreviewClick,
    // Batch actions
    handleBatchDeleteClick,
    handleBatchMoveClick,
    handleBatchDownload,
    handleBatchDeleteConfirm,
    handleBatchMoveConfirm,
    closeBatchDeleteDialog,
    closeBatchMoveDialog,
    // Dialog confirm/close
    handleRenameConfirm,
    handleDeleteConfirm,
    handleMoveConfirm,
    closeShareDialog,
    openCreateFolderDialog,
    closeCreateFolderDialog,
    handleCreateFolderConfirm,
    // Dialog states
    confirmDialog,
    closeConfirmDialog,
    renameDialog,
    closeRenameDialog,
    moveDialog,
    closeMoveDialog,
    detailsDialog,
    closeDetailsDialog,
    editorDialog,
    closeEditorDialog,
    imagePreviewDialog,
    closeImagePreviewDialog,
    pdfPreviewDialog,
    closePdfPreviewDialog,
    audioPlayerDialog,
    closeAudioPlayerDialog,
    videoPlayerDialog,
    closeVideoPlayerDialog,
    createFolderDialogOpen,
    shareItem,
    batchDeleteDialog,
    batchMoveDialog,
  };
}

/**
 * SharedListRow -- Row component for the top-level shared items list.
 *
 * Extracted from SharedFileBrowser.tsx.
 */

import type { MouseEvent } from 'react';
import type { SharedListItem } from '../../hooks/useSharedNavigation';

/**
 * Truncate a public key for display: 0x{first4}...{last4}
 */
function truncatePubkey(pubkey: string): string {
  if (pubkey.length <= 12) return pubkey;
  const hex = pubkey.startsWith('0x') ? pubkey.slice(2) : pubkey;
  return `0x${hex.slice(0, 4)}...${hex.slice(-4)}`;
}

export type SharedListRowProps = {
  sharedItem: SharedListItem;
  onOpen: () => void;
  onContextMenu: (e: MouseEvent) => void;
};

export function SharedListRow({ sharedItem, onOpen, onContextMenu }: SharedListRowProps) {
  const { share } = sharedItem;
  const isFolder = share.itemType === 'folder';
  const icon = isFolder ? '\uD83D\uDCC1' : '\uD83D\uDCC4';
  const date = new Date(share.createdAt).toLocaleDateString();
  const isWrite = share.permission === 'write';

  return (
    <div
      className="file-list-row shared-list-row"
      role="row"
      tabIndex={0}
      onDoubleClick={onOpen}
      onContextMenu={(e) => {
        e.preventDefault();
        onContextMenu(e);
      }}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onOpen();
        }
      }}
    >
      <div className="file-list-cell file-list-cell-name" role="gridcell">
        <span className="file-icon">{icon}</span>
        <span className="file-name">
          {share.itemName}
          {isFolder ? '/' : ''}
        </span>
        {isWrite ? (
          <span className="shared-rw-badge">{'[RW]'}</span>
        ) : (
          <span className="shared-ro-badge">{'[RO]'}</span>
        )}
      </div>
      <div className="file-list-cell shared-by-cell" role="gridcell">
        {truncatePubkey(share.sharerPublicKey)}
      </div>
      <div className="file-list-cell file-list-cell-date" role="gridcell">
        {date}
      </div>
    </div>
  );
}

/**
 * SharedFolderRow -- Row component for items within a shared folder.
 *
 * Extracted from SharedFileBrowser.tsx.
 * Shows [RW] or [RO] badge based on the share's permission level.
 * Supports inline renaming when isRenaming is true.
 */

import type React from 'react';
import type { MouseEvent } from 'react';
import type { FolderChild } from '@cipherbox/core';

export type SharedFolderRowProps = {
  item: FolderChild;
  permission: 'read' | 'write' | null;
  isRenaming: boolean;
  renameValue: string;
  renameInputRef: React.RefObject<HTMLInputElement>;
  onRenameChange: (value: string) => void;
  onRenameKeyDown: (e: React.KeyboardEvent) => void;
  onRenameSubmit: () => void;
  onContextMenu: (e: MouseEvent) => void;
  onDoubleClick: () => void;
};

export function SharedFolderRow({
  item,
  permission,
  isRenaming,
  renameValue,
  renameInputRef,
  onRenameChange,
  onRenameKeyDown,
  onRenameSubmit,
  onContextMenu,
  onDoubleClick,
}: SharedFolderRowProps) {
  const isFolder = item.type === 'folder';
  const icon = isFolder ? '\uD83D\uDCC1' : '\uD83D\uDCC4';
  const date = item.modifiedAt ? new Date(item.modifiedAt).toLocaleDateString() : '--';
  const isWrite = permission === 'write';

  return (
    <div
      className="file-list-row"
      role="row"
      tabIndex={0}
      onDoubleClick={isRenaming ? undefined : onDoubleClick}
      onContextMenu={(e) => {
        e.preventDefault();
        onContextMenu(e);
      }}
      onKeyDown={(e) => {
        if (isRenaming) return;
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onDoubleClick();
        }
      }}
    >
      <div className="file-list-cell file-list-cell-name" role="gridcell">
        <span className="file-icon">{icon}</span>
        {isRenaming ? (
          <input
            ref={renameInputRef}
            type="text"
            className="shared-inline-rename-field"
            value={renameValue}
            onChange={(e) => onRenameChange(e.target.value)}
            onKeyDown={onRenameKeyDown}
            onBlur={onRenameSubmit}
            aria-label="Rename item"
          />
        ) : (
          <>
            <span className="file-name">
              {item.name}
              {isFolder ? '/' : ''}
            </span>
            {isWrite ? (
              <span className="shared-rw-badge">{'[RW]'}</span>
            ) : (
              <span className="shared-ro-badge">{'[RO]'}</span>
            )}
          </>
        )}
      </div>
      <div className="file-list-cell file-list-cell-size" role="gridcell">
        --
      </div>
      <div className="file-list-cell file-list-cell-date" role="gridcell">
        {date}
      </div>
    </div>
  );
}

