2	 * @cipherbox/sdk - Share key cache with TTL
3	 *
4	 * Caches fetched share keys per shareId with a configurable TTL.
5	 */
6	
7	/**
8	 * A cached share key entry.
9	 */
10	export type CachedShareKey = {
11	  keyType: string;
12	  itemId: string;
13	  encryptedKey: string;
14	};
15	
16	/**
17	 * TTL-based cache for share keys.
18	 * Avoids redundant API calls when navigating within a share.
19	 */
20	export class ShareKeyCache {
21	  private cache = new Map<string, { keys: CachedShareKey[]; fetchedAt: number }>();
22	  private ttlMs: number;
23	
24	  /**
25	   * @param ttlMs - Cache entry lifetime in milliseconds (default: 30000 = 30s)
26	   */
27	  constructor(ttlMs = 30_000) {
28	    this.ttlMs = ttlMs;
29	  }
30	
31	  /**
32	   * Get cached keys for a share, or null if expired/missing.
33	   *
34	   * @param shareId - The share ID to look up
35	   * @returns Cached keys array or null
